#!/bin/sh
# Demo script: Executes the exact GitHub Actions workflow (.github/workflows/ai-testing-tool-vitest.yml)
# generated by Jira Testing Tool → CI/CD Pipeline → GitHub Actions → Setup (project ES).
#
# Usage:
#   sh docs/github-actions/demo-github-actions.sh

set -eu
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"

# Keep working tree clean after running demo
cleanup() {
  git checkout -- ai-testing-tool-results.json 2>/dev/null || true
}
trap cleanup EXIT

export AI_TESTING_TOOL_ENV_FILE="${AI_TESTING_TOOL_ENV_FILE:-$ROOT/.env}"
. scripts/load-ingest-env.sh

export GITHUB_ACTIONS="true"
export GITHUB_SERVER_URL="${GITHUB_SERVER_URL:-https://github.com}"
export GITHUB_REPOSITORY="${GITHUB_REPOSITORY:-ai-testing-tool/testing-tool-js}"
export GITHUB_RUN_ID="${GITHUB_RUN_ID:-987654321}"
export GITHUB_RUN_NUMBER="${GITHUB_RUN_NUMBER:-42}"
export GITHUB_WORKFLOW="${GITHUB_WORKFLOW:-AiTestingTool Vitest}"
export GITHUB_SHA="${GITHUB_SHA:-$(git rev-parse HEAD)}"
export GITHUB_REF_NAME="${GITHUB_REF_NAME:-$(git rev-parse --abbrev-ref HEAD)}"
export GITHUB_ACTOR="${GITHUB_ACTOR:-$(git log -1 --pretty=format:%an)}"
export JIRA_PROJECT_KEY="${JIRA_PROJECT_KEY:-${AI_TESTING_TOOL_PROJECT_KEY:-ES}}"

echo "=================================================================="
echo " GitHub Actions Workflow Demo (.github/workflows/ai-testing-tool-vitest.yml)"
echo "=================================================================="
echo "  Repository       : $GITHUB_REPOSITORY"
echo "  Branch / SHA     : $GITHUB_REF_NAME ($GITHUB_SHA)"
echo "  Actor            : $GITHUB_ACTOR"
echo "  Workflow         : $GITHUB_WORKFLOW (Run #$GITHUB_RUN_NUMBER / ID $GITHUB_RUN_ID)"
echo "  Build URL        : $GITHUB_SERVER_URL/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID"
echo "  JIRA_PROJECT_KEY : $JIRA_PROJECT_KEY (https://pipevo.atlassian.net/jira/software/projects/$JIRA_PROJECT_KEY)"
echo "=================================================================="

echo ""
echo "==> [Step 1/2] Running: npx vitest run --reporter=json --outputFile=ai-testing-tool-results.json"
npx vitest run --reporter=json --outputFile=ai-testing-tool-results.json

if [ -n "${AI_TESTING_TOOL_INGEST_URL:-}" ] && [ -n "${AI_TESTING_TOOL_INGEST_TOKEN:-}" ]; then
  echo ""
  echo "==> [Step 2/2] Upload to AiTestingTool (LIVE Forge Web Trigger: $AI_TESTING_TOOL_INGEST_URL)"
  npx @ai-testing-tool/forge-api-client \
    --project "$JIRA_PROJECT_KEY" \
    --launch "${GITHUB_WORKFLOW} #${GITHUB_RUN_NUMBER}" \
    --report ai-testing-tool-results.json
else
  echo ""
  echo "==> [Step 2/2] Upload to AiTestingTool (Local qa-analyzer Forge Web Trigger emulator)"
  echo "    (Tip: Copy docs/github-actions/.env.example to .env to push live to pipevo.atlassian.net)"
  node -e '
    const http = require("node:http");
    const { spawn } = require("node:child_process");

    const received = [];
    const server = http.createServer((req, res) => {
      if (req.method === "GET") {
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ ok: true, executionSyncStatus: "synced" }));
        return;
      }
      let body = "";
      req.on("data", (chunk) => { body += chunk; });
      req.on("end", () => {
        const auth = req.headers["authorization"] || "";
        if (auth !== "Bearer qa_demo_github_actions_token") {
          res.writeHead(401, { "Content-Type": "application/json" });
          res.end(JSON.stringify({ error: "Unauthorized" }));
          return;
        }
        const payload = JSON.parse(body);
        const assertions = (payload.report?.testResults || []).flatMap((r) => r.assertionResults || []);
        const issueKeys = [...new Set(assertions.flatMap((a) => a.meta?.qa?.issueKeys || []))];
        const stepsCount = assertions.reduce((n, a) => n + (a.meta?.qa?.steps?.length || 0), 0);
        received.push({
          projectKey: payload.projectKey,
          launchName: payload.launchName,
          format: payload.format,
          ciPlatform: payload.ciPlatform,
          ciBuildUrl: payload.ciBuildUrl,
          gitBranch: payload.gitBranch,
          gitCommitSha: payload.gitCommitSha ? payload.gitCommitSha.slice(0, 8) : null,
          gitAuthorName: payload.gitAuthorName,
          gitHashCommitUrl: payload.gitHashCommitUrl,
          totalTests: payload.report?.numTotalTests ?? assertions.length,
          passedTests: payload.report?.numPassedTests ?? 0,
          linkedIssueKeys: issueKeys,
          linkedIssueCount: issueKeys.length,
          stepsCount,
        });
        res.writeHead(201, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ ok: true }));
      });
    });

    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address();
      const url = `http://127.0.0.1:${port}/ai-testing-tool-ingest-launch`;
      console.log(`    Emulator listening at ${url}`);

      const projectKey = process.env.JIRA_PROJECT_KEY || "ES";
      const launchName = `${process.env.GITHUB_WORKFLOW || "AiTestingTool Vitest"} #${process.env.GITHUB_RUN_NUMBER || "42"}`;

      const child = spawn(
        "npx",
        [
          "@ai-testing-tool/forge-api-client",
          "--project",
          projectKey,
          "--launch",
          launchName,
          "--report",
          "ai-testing-tool-results.json",
        ],
        {
          stdio: "inherit",
          env: {
            ...process.env,
            AI_TESTING_TOOL_INGEST_URL: url,
            AI_TESTING_TOOL_INGEST_TOKEN: "qa_demo_github_actions_token",
          },
        },
      );

      child.on("close", (code) => {
        console.log("\n==================================================================");
        console.log(" Forge Web Trigger Ingest Summary (qa-analyzer contract verified)");
        console.log("==================================================================");
        console.table(received.map((r) => ({
          project: r.projectKey,
          launchName: r.launchName,
          ciPlatform: r.ciPlatform,
          branch: r.gitBranch,
          sha: r.gitCommitSha,
          tests: `${r.passedTests}/${r.totalTests}`,
          steps: r.stepsCount,
          linkedIssues: `${r.linkedIssueCount} keys (${r.linkedIssueKeys.slice(0, 5).join(", ")}${r.linkedIssueCount > 5 ? "..." : ""})`,
        })));
        if (received[0]) {
          console.log("  Sample ciBuildUrl       :", received[0].ciBuildUrl);
          console.log("  Sample gitHashCommitUrl :", received[0].gitHashCommitUrl);
          console.log("  Pilot ES Issue Keys     :", received[0].linkedIssueKeys.filter((k) => /^ES-1\d\d$/.test(k)).join(", "));
        }
        server.close(() => process.exit(code ?? 0));
      });
    });
  '
fi
